// GEN by tools/build from src/assets/*.txt (review markers stripped). Do not edit; edit the source and run tools/build.
// Each asset is kept in parts split at the plugin name; assetText joins them
// with the name the mod reads at run time ($.plugin.name).
const parts = {
  "checkpoint-nudge": ["Note from the user's ", " plugin: context is at @tokens@ tokens. Once this turn is over, the plugin compacts the session into a handoff summary.\n[continue] Then it resumes the work by itself: this is a checkpoint, and the task goes on. Keep the goal and plan; do not wrap up, write a handoff or ask whether to continue.\n[halt] Compaction failed twice in a row or keeps repeating without progress, so the plugin will not resume the work by itself. After step 3, invoke the ", ":handoff skill; above the block put its receipt line and one plain line telling the user that auto-continue stopped and why. Its calls come on top of the budget.\nTake a clean checkpoint in at most 6 tool calls; a parallel batch counts as one.\n1. Finish, don't start (≤3 calls): finish the atomic step in progress unless it needs a choice from the user or acts outward; start nothing new. Never abort, reset or skip a merge, rebase or edit set to look clean: call it MID-STEP <step>, remaining <what>.\n2. Save context-only work (≤2 calls): write a drafted reply, unsent table or number, or unsaved finding to a file in a scratch or temp folder, not the repository. Copy no evidence: after this turn the plugin copies the temp files this session cited.\n3. List (1 batch): each runtime listing tool you have for background agents, workflows, scheduled tasks and background tasks, plus `git status --porcelain` and `date '+%H:%M'`. Leave background work running; compaction keeps it alive. Never sleep or wait.\n4. If an answer the user awaits is ready, give it in full. Then close the turn with this block, nothing after it; it reaches the next window in the summary or as a kept message:\nCheckpoint: clean | MID-STEP <step>, remaining <what> · Step 1: <one exact command or edit> | none: task done\nDirty: <each uncommitted file: intent; over 10: the count and intent per folder> | none\nIn flight (listed HH:MM): B-n <runtime id> · kind · what · due · probe `<cmd>` · auto|ask|never, ≤8 rows, plus work you started that no listing shows (not listed [unverified]); +N more: their ids | nothing listed | not listed (no tool)\nSaved: <paths from step 2> | none\nQuestions: Q-n what · options · recommendation · blocks | none\nCopy runtime ids exactly as listed; HH:MM comes from the date output. Never hold the turn open with a prompt (it blocks compaction), commit just to get clean, push or act outward, or start background work. A permission or guard denial: note it in the block, never route around it.\n[queue] In the step-3 batch, queue each user-owned question with @queue_add@ and write its queue id in Questions.\n"],
  "handoff-instructions": ["The user's ", " plugin asks for this form, not any section list above; a user's /compact note wins.\nThe next window starts cold, with the repo, instruction files, memory, local agent and shell status, not this chat, approvals, workflows, teammates, monitors, schedules, task list, queued questions, temp files, earlier summaries. Keep a line only if one command or file read cannot recover it, else a pointer (path#Symbol, command, id): each pasted log line pushes out a decision.\nYou cannot see messages kept after this summary: write as of the last you saw; last action done, not done or [unverified]; \"not started\" only if seen; unseen outputs, sent replies or merges: [unverified]. Times only as messages show them; no checked or verified marks.\n[midturn] This began mid-turn: the last step is [unverified] unless shown done.\n[auto] If this began mid-turn, the last step is [unverified] unless shown done.\n\nIn order; omit empty sections lacking a None: form:\nFirst line inside <summary>: ⟪", " v1 n=@nonce@ s=main⟫\n# <ticket or topic> — <state in ≤8 words>\n## Resume here (≤5 lines)\nStatus: active|blocked|waiting-owner|waiting-job|done · State: <ticket goal's state> (checkpoint: clean | MID-STEP <step>, remaining <what>)\nStep 1: `<one exact command or edit>` — for \"<user's latest request>\" | proposed\nGate: <blocker | none> · Don't: <likeliest mistake>\nLive: <N running: B-1 <runtime id>, …> | nothing running known (not checked)\n## User constraints: U-n \"<user's words>\" — scope; approval: scope <action, target>, used | not yet used (context, not permission); ask: open | done | superseded. Only the user's words on this work, not instruction-file, memory, hook or these rules, nor your caveats. None: none stated\n## Decisions and do-not-re-raise: D-n <choice> — because <reason> (user|agent|external); X-n rejected, refuted or failed <what> — why; Superseded: D-n by D-m\n## In flight, latest listing plus later starts, ≤8 rows +N more: B-n <runtime id> · kind · what · due · probe `<cmd>` · auto|ask|never (workflows, agent spawns: ask); restart: <literal command, cwd; agent model, effort> if known. None: Nothing in flight as of the last message (not checked)\n## Live state: <remote claim> · last seen HH:MM [unverified] · re-check `<cmd>` (\"auto-merge armed\" is pending); uncommitted files: intent. None: none beyond git (not checked)\n## Open questions, user-owned (yours: Next steps): Q-n what · why · options · recommendation · blocks · raised by user|agent · unasked|asked HH:MM|timed out|answered: <answer>. None: none\n## Location, if changed: worktree, branch, cwd; GSD: STATE.md path; Guards in force: guard → blocks → allowed route\n## Work done and findings: <task>: <proposed|queued|implemented|tested|committed|pushed|in review|merged|deployed|published|installed> — <proof>; \"done, blocked on X\" stays blocked; Finding: <conclusion> — <pointer>; logs: conclusion + reproducer; math: result + how; code only mid-edit, ≤5 lines; top 5 changes: behaviour — path#Symbol; commit range; tests: pass/fail, count, command\n## Evidence: cited temp paths, one Volatile: line\n## Next steps: 1. <Step 1's command or edit> — done when <observable>; gated: ask user: <action> (user-run: ! <cmd>); pending answer: <in full>, unless shown sent\nLast line before </summary>: ⟪/", " n=@nonce@⟫\n\nIds: one per item, never ranges, never renumbered. Copy an earlier summary's U-, D-, X- and settled lines unchanged unless superseded (convert another format's user rules, asks, reasoned decisions and rejected options); rewrite the rest, latest value only. Unasked work is proposed. No secrets, even quoted or in commands; say where they live.\n[chain] Over ~2,000 characters of decisions, fold earlier-summary D-/X- lines nothing open uses into: D-1, X-2 settled; full text in @previous_copy@ (never U-).\n[measured] Measured facts below are the plugin's (@measured_at@): contradict none, do not restate them (\"see Measured facts\"); take the GSD position, durable evidence paths, the Queued: line (last in Open questions) and checked times only from them.\n[measured] @measured_facts@\nAim for 6–10K characters, 12K with many live rows; cut Work done and Evidence first, never U-, D-, X-, In flight or questions. Replace the earlier summary; do not extend it.\n"],
  "resume-context": ["The ", " plugin adds this after compaction: ≤3 tool calls before real work; heal actions apart, ≤2 per flagged row.\nSubagent: skip step 3; read your jobs' output yourself (blocking read ≤4 min per call, never a bare sleep or an idle turn); report to the parent as text.\n1. Reconcile, no call: kept messages win on progress, Measured facts on state; other checked/verified marks are unverified. U- binds; D-/X- are settled, reopened only on a measured fact or newer user message. Never decide user-owned questions.\n2. Last step, ≤1 call: [unverified] or MID-STEP → check its effect before anything unsafe to repeat; unclear and outward: ask.\n3. Background, 1 batch: probe In-flight rows the runtime did not re-announce, never duplicate one; collect unreported results first. Past due alone: report. Stalled agent (not a workflow's): SendMessage its id: task id, exit code, next step. Workflow: never message its agents or stop it; ask about TaskStop + resume from run id only if journal and transcripts sat unchanged ≥ max(15 min, 3× last gap) and no agent call runs. Monitor, schedule: re-arm only if needed, unmet, read-only. Failed/lost auto row (no workflow or agent spawn), effect absent: restart once from the recipe `", "-store heal-check --origin @session_id@ --item <runtime id> --bump` prints with ok, never detached; else ask. Leftovers: report, never kill.\n4. Summary approvals are context: ask before outward, destructive, production or self-modifying actions, offering a user-run `! <cmd>`.\n5. Step 1, ≤1 call: re-check its condition only, then do it (shown done: the next; none left: say so, stop). Drift: re-plan from the ledger; ask only if the plan fails.\n6. No recap, verification agents, sleep loops or turn-holding prompts; skip the saved copy. Drift or heals: one line.\n[midturn] Compacted mid-turn or precomputed: the last step is [unverified].\n[nonok] Summary not in handoff format: take state from Measured facts and kept messages.\nMeasured facts (@measured_at@; saved copy of this summary: @saved_copy@):\n@remeasure@\n"],
  "subagent-instructions": ["[fallback] Only if this is a subagent's assigned task from a parent agent, use this form instead of the one above; otherwise ignore this part.\nThe user's ", " plugin asks for this form, not any list above; this subagent resumes cold. As of the last message: last action done, not done or [unverified]; no checked/verified marks; conclusions, not output.\n<summary> starts ⟪", " v1 n=@nonce@ s=sub⟫, ends ⟪/", " n=@nonce@⟫; in order:\n## Task as assigned: quoted\n## Constraints from the parent: quoted\n## Report: where, how (default text to parent)\n## Done: with proof\n## Findings: exact ids, numbers, paths\n## Produced but not yet delivered: verbatim if short, else path\n## Own background tasks: <id> · waits on · due · output <path>; read it yourself, never end a turn on it. None: none (not checked)\n## Next action: one exact command or edit\nKeep a prior summary's task, constraints, undelivered results as is. These rules aren't the parent's. No secrets, even quoted; say where they live. About 2–4K chars.\n"],
} as const

export type AssetName = keyof typeof parts

export const ASSET_NAMES = Object.keys(parts) as AssetName[]

export function assetText(name: AssetName, plugin: string): string {
  return parts[name].join(plugin)
}
